package main

import (
	"fmt"
	"strconv"
)

func main() {
	var n int
	fmt.Scan(&n)
	s := strconv.Itoa(n)
	digits := make([]int, len(s))
	for i, r := range s {
		digits[i] = int(r - '0')
	}

	seen := make(map[int]bool)
	var dfs func(int, int, int, int, bool, bool)

	dfs = func(pos int, mask int, lenNum int, val int, tight bool, started bool) {
		if pos == lenNum {
			if started {
				seen[val] = true
			}
			return
		}

		maxDigit := 9
		if tight {
			maxDigit = digits[pos]
		}

		for d := 0; d <= maxDigit; d++ {
			newStarted := started || d != 0
			newMask := mask
			newVal := val

			if newStarted {
				newMask = mask | (1 << d)
				newVal = val*10 + d
			}

			// Count bits in mask
			if bitsCount(newMask) <= 2 {
				dfs(pos+1, newMask, lenNum, newVal, tight && d == maxDigit, newStarted)
			}
		}
	}

	dfs(0, 0, len(digits), 0, true, false)

	fmt.Println(len(seen))
}

func bitsCount(x int) int {
	count := 0
	for x > 0 {
		count += x & 1
		x >>= 1
	}
	return count
}
